// Regenerates docs/generators.md from the generator registry: node scripts/gen-docs.mjs
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { listGenerators } from '../src/generators/index.js';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const esc = (s) => String(s ?? '').replace(/\|/g, '\\|');
let md = `# Generators

<!-- generated by scripts/gen-docs.mjs — do not edit by hand -->

Use a generator anywhere a blueprint is accepted: \`mcb preview gen:<name> -p key=value …\`,
\`mcb build gen:<name> …\`, JSON \`{ "generator": "<name>", "params": { … } }\` / \`parts\`, or
\`ctx.gen('<name>', { … })\` inside a JS blueprint.

Conventions: \`y = 0\` is the first layer above the ground, the footprint's north-west corner is at
\`x = z = 0\`, and the front (door, facade, readable text) faces **south**. Every generator is
deterministic; \`-p seed=N\` varies the random details.

`;
for (const g of listGenerators()) {
  md += `## \`${g.name}\`\n\n${g.description}\n\n| Param | Type | Default | Notes |\n|---|---|---|---|\n`;
  for (const [k, p] of Object.entries(g.params ?? {})) {
    const range = p.values ? p.values.join(' \\| ') : p.min !== undefined || p.max !== undefined ? `${p.min ?? ''}…${p.max ?? ''}` : '';
    md += `| \`${k}\` | ${p.type}${range ? ` (${range})` : ''} | \`${esc(JSON.stringify(p.default))}\` | ${esc(p.description)} |\n`;
  }
  md += `\n\`\`\`bash\nmcb preview gen:${g.name} -o ${g.name}.png\n\`\`\`\n\n`;
}
fs.writeFileSync(path.join(root, 'docs', 'generators.md'), md);
console.log(`wrote docs/generators.md (${listGenerators().length} generators)`);
